#!/usr/bin/env sh

# Colors and fonts generated by Home Manager from lib/theme.
theme_colors="${XDG_CONFIG_HOME:-${HOME}/.config}/theme/sketchybar.sh"

if [ ! -r "$theme_colors" ]; then
	printf 'Missing SketchyBar theme colors: %s\n' "$theme_colors" >&2
	return 1 2>/dev/null || exit 1
fi

# shellcheck source=/dev/null
. "$theme_colors"
